window.addEventListener('DOMContentLoaded',()=>{'use strict';
const animal=document.getElementById('animal'),byId=id=>document.getElementById(id);
const notes={
 'sea-angel':{title:'Sea angel',latin:'Clione limacina',description:'A translucent body with a warm visceral core. Two flexible wings scull through the water.',anatomy:'Cephalic tentacles · translucent trunk · internal mass · paired parapodia',movement:'Root-led wing strokes, delayed tips and a small trailing-edge twist. The trunk stays quiet.',research:'Szymik & Satterlie (2011) measured three-dimensional wing motion and different slow and fast swimming gaits. Flexible wing strokes inform this interpretation; this preview uses a slow 2 Hz rhythm at 1×.',url:'https://pubmed.ncbi.nlm.nih.gov/22071184/'},
 jellyfish:{title:'Moon jelly',latin:'Aurelia aurita · interpretation',description:'Light catches a scalloped bell, radial canals and four inner loops. The oral arms drift beneath it.',anatomy:'Domed bell · radial canals · four gonad loops · fine marginal tentacles · oral arms',movement:'A short contraction, a longer refill, then a quiet glide. Arms trail behind the bell.',research:'Gemmell et al. (2013) measured passive energy recapture during bell refilling in Aurelia aurita. The bell cycle and gliding character are informed by that work. No wake forces are calculated here.',url:'https://pubmed.ncbi.nlm.nih.gov/24101461/'},
 ray:{title:'Ray',latin:'Dasyatis-type · interpretation',description:'A raised central body sits within a thin diamond disc. Undulations travel along its outer margins.',anatomy:'Pectoral disc · raised head · paired eye rims · spiracles · pelvic fins · whip-like tail',movement:'About 1.3 traveling waves along the disc, with greater movement toward the fin edge.',research:'Rosenberger (2001) compared eight batoids across an undulation–oscillation continuum. Dasyatis sabina and D. say averaged 1.3 waves per fin length. This disc uses that pattern as a design reference.',url:'https://pubmed.ncbi.nlm.nih.gov/11136623/'},
 koi:{title:'Koi',latin:'Cyprinus carpio · ornamental form',description:'A fuller body, a forked tail and soft rose patches. Scales follow the body rather than a flat cutout.',anatomy:'Wrapped scale field · gill arch · mouth barbels · pectoral fins · forked caudal fin',movement:'A brief series of tail beats gives way to a quieter coast. Posterior bending fades while the pectoral fins continue to trim.',research:'Wu, Yang & Zeng (2007) measured burst-and-coast swimming in koi carp. That alternating gait informs this motion and its roaming speed. The body-wave envelope remains a general fish surrogate; timings and path are art directed.',url:'https://doi.org/10.1242/jeb.001842'},
 betta:{title:'Betta',latin:'Betta splendens · long-fin study',description:'The original violet fish, with a closer scale field, an opercular arch and more directional light.',anatomy:'Rounded trunk · opercular arch · scale glints · broad caudal fan · dorsal, anal and pectoral fins',movement:'A quiet trunk, a restrained posterior wave and independently delayed membranes. The broad tail yields behind the body.',research:'The general posterior body-wave model is informed by Di Santo et al. (2021). The long-fin membrane lag and fin rates are artistic choices, not a measured Betta kinematic reconstruction.',url:'https://pubmed.ncbi.nlm.nih.gov/34853171/'},
 pisces:{title:'Paired fish',latin:'Pisces motif · two ornamental fish',description:'Anima’s paired-fish motif becomes two volumetric swimmers, each with its own stroke phase.',anatomy:'Two wrapped bodies · forked tails · gill lines · paired pectoral fins · eye rims',movement:'Two offset body waves. The composition is a symbolic pair, rather than a separate biological species.',research:'The fish share the general quadratic body-wave interpretation from Di Santo et al. (2021), with a different phase for each individual. Their arrangement and shared route are composed for Anima.',url:'https://pubmed.ncbi.nlm.nih.gov/34853171/'}
};
function updateCounts(){byId('counts').textContent=Number(animal.dataset.glyphs||0).toLocaleString()+' GLYPHS / SEEDED';}
function label(){const paused=animal.hasAttribute('paused');byId('motion').textContent=paused?'Resume':'Pause';byId('motion').setAttribute('aria-pressed',String(!paused));}
function select(species){const n=notes[species];animal.setAttribute('species',species);byId('specimen').textContent=n.latin.toUpperCase();byId('animal-title').textContent=n.title;for(const id of ['description','anatomy','movement','research'])byId(id).textContent=n[id];byId('source').href=n.url;document.querySelectorAll('[data-species]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.species===species)));updateCounts();byId('status').textContent=n.title+' / independent anatomy and motion.';history.replaceState(null,'','#'+species);}
document.querySelectorAll('[data-species]').forEach(b=>b.onclick=()=>select(b.dataset.species));
for(const id of ['behavior','appearance','detail'])byId(id).onchange=e=>{animal.setAttribute(id,e.target.value);updateCounts();};
for(const id of ['speed','light'])byId(id).oninput=e=>{animal.setAttribute(id,e.target.value);if(id==='speed')byId('speed-value').textContent=Number(e.target.value)+'×';};
byId('motion').onclick=()=>{animal.toggleAttribute('paused');label();};animal.addEventListener('playchange',label);animal.addEventListener('geometrychange',updateCounts);
byId('profile').onclick=()=>animal.resetView();byId('save').onclick=()=>{const a=document.createElement('a');a.download='anima-'+animal.species+'.png';a.href=animal.saveFrame();a.click();byId('status').textContent='Saved a transparent PNG frame.';};
const initial=location.hash.slice(1);select(notes[initial]?initial:'sea-angel');label();
});
